{"content": "1|// Real CpuModel for CPU-only builds with GGUF loading support
2|use crate::gguf_weight_loader::{load_gguf_weights, GgufWeights};
3|use std::path::Path;
4|
5|/// CPU model implementation for testing K-family dequantization.
6|///
7|/// Loads token_embeddings and output.weight tensors for single-token inference.
8|pub struct CpuModel {
9|    /// GGUF weights loaded from file
10|    pub weights: GgufWeights,
11|    /// Token embeddings matrix (vocab_size × hidden_size)
12|    pub token_embeddings: Option<Vec<f32>>,
13|    /// Output head weights (vocab_size × hidden_size)
14|    pub output_weights: Option<Vec<f32>>,
15|    /// Hidden size from config
16|    pub hidden_size: usize,
17|    /// Vocabulary size from config
18|    pub vocab_size: usize,
19|    /// Whether dispatch is enabled
20|    pub use_dispatch: bool,
21|}
22|
23|impl CpuModel {
24|    /// Load minimal GGUF model for conformance testing.
25|    ///
26|    /// Only loads necessary tensors (token_embeddings + output.weight), skipping
27|    /// transformer layers for now since we're testing dequantization only.
28|    pub fn load_gguf(path: &Path) -> Result<Self> {
29|        let weights = load_gguf_weights(path)?;
30|
31|        // Extract config values
32|        let hidden_size = weights.header.embedding_length()
33|            .map(|v| v as usize)
34|            .ok_or_else(|| {
35|                crate::error::RunnerError::Gguf(pesti_gguf::GgufError::Io(
36|                    "Missing llama.embedding_length".to_string(),
37|                ))
38|            })?;
39|
40|        // Get vocab size from tokens array (number of tokens)
41|        let vocab_size = weights.header.get_kv_array("tokenizer.ggml.tokens")
42|            .map(|arr| arr.len())
43|            .unwrap_or(32000); // Default fallback
44|
45|        // Load token embeddings (various naming conventions)
46|        let token_embeddings = match weights.tensors.get("token_embd.weight")
47|            .or_else(|| weights.tensors.get("tok_embeddings.weight"))
48|            .or_else(|| weights.tensors.get("model.embed_tokens.weight")) {
49|            Some(bytes) => {
50|                // For now, assume F16 quantization and dequantize to f32
51|                if bytes.len() % 2 == 0 {
52|                    let f16_bytes: Vec<u16> = bytes.chunks(2)
53|                        .map(|chunk| u16::from_le_bytes([chunk[0], chunk[1]]))
54|                        .collect();
55|                    Some(f16_bytes.iter()
56|                        .map(|&x| half::f16::from_bits(x).to_f32())
57|                        .collect())
58|                } else {
59|                    // Fallback: assume f32 storage
60|                    Some(bytes.chunks(4)
61|                        .map(|chunk| u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
62|                        .map(|x| f32::from_bits(x))
63|                        .collect())
64|                }
65|            },
66|            None => None,
67|        };
68|
69|        // Load output head (usually named "output.weight" or "lm_head.weight")
70|        let output_weights = match weights.tensors.get("output.weight")
71|            .or_else(|| weights.tensors.get("lm_head.weight")) {
72|            Some(bytes) => {
73|                // Same dequantization logic as token embeddings
74|                if bytes.len() % 2 == 0 {
75|                    let f16_bytes: Vec<u16> = bytes.chunks(2)
76|                        .map(|chunk| u16::from_le_bytes([chunk[0], chunk[1]]))
77|                        .collect();
78|                    Some(f16_bytes.iter()
79|                        .map(|&x| half::f16::from_bits(x).to_f32())
80|                        .collect())
81|                } else {
82|                    // Fallback: assume f32 storage
83|                    Some(bytes.chunks(4)
84|                        .map(|chunk| u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
85|                        .map(|x| f32::from_bits(x))
86|                        .collect())
87|                }
88|            },
89|            None => None,
90|        };
91|
92|        Ok(Self {
93|            weights,
94|            token_embeddings,
95|            output_weights,
96|            hidden_size,
97|            vocab_size,
98|            use_dispatch: false,
99|        })
100|    }
101|
102|    /// Embed a single token into hidden space.
103|    pub fn embed(&self, token: u32, _seq_len: usize) -> Result<Vec<f32>> {
104|        let embeddings = self.token_embeddings.as_ref().ok_or_else(|| {
105|            crate::error::RunnerError::Internal("Token embeddings not loaded".to_string())
106|        })?;
107|
108|        // Simple lookup: each row is hidden_size elements
109|        Ok(embeddings[token as usize * self.hidden_size..(token + 1) as usize * self.hidden_size].to_vec())
110|    }
111|
112|    /// Apply output head to get logits.
113|    pub fn apply_output_head(&self, hidden: &[f32]) -> Result<Vec<f32>> {
114|        let output_weights = self.output_weights.as_ref().ok_or_else(|| {
115|            crate::error::RunnerError::Internal("Output weights not loaded".to_string())
116|        })?;
117|
118|        // Simple matrix-vector multiply: logits = hidden @ output_weights.T
119|        let mut logits = vec![0.0f32; self.vocab_size];
120|
121|        for (row_idx, row) in output_weights.chunks(self.hidden_size).enumerate() {
122|            let mut sum = 0.0;
123|            for (col_idx, &hidden_val) in hidden.iter().enumerate() {
124|                sum += hidden_val * row[col_idx];
125|            }
126|            logits[row_idx] = sum;
127|        }
128|
129|        Ok(logits)
130|    }
131|
132|    /// Decode token to logits (embed → output head).
133|    pub fn decode(&self, token: u32) -> Result<Vec<f32>> {
134|        let hidden = self.embed(token, 0)?;
135|        self.apply_output_head(&hidden)
136|    }
137|
138|    /// Enable GPU dispatch (no-op for CPU-only builds).
139|    pub fn enable_dispatch(&mut self) {
140|        self.use_dispatch = true;
141|    }
142|
143|    /// Check if dispatch can be used.
144|    pub fn can_use_dispatch(&self) -> bool {
145|        self.use_dispatch
146|    }
147|
148|    /// Forward pass through layers (stub - returns input for now).
149|    pub fn forward_with_dispatch(&self, hidden: &[f32], _start_pos: usize) -> Result<Vec<f32>> {
150|        // For now, just return the hidden state (no actual layer computation)
151|        Ok(hidden.to_vec())
152|    }
153|
154|    /// Forward through transformer layers.
155|    pub fn forward_layers(&self, _hidden: &[f32], _start_pos: usize) -> Result<Vec<f32>> {
156|        // Stub - returns input for testing dequantization only
157|        Ok(_hidden.to_vec())
158|    }
159|}
