{"content": "1|//! CPU-only transformer implementation for pure-Rust inference.
2|//!
3|//! This module provides a complete forward pass through a Llama-style transformer model
4|//! using only CPU computation (no CUDA dependencies). It wires together the primitive
5|//! operations: RMSNorm, RoPE, attention, and SwiGLU feed-forward networks.
6|
7|pub mod layer;
8|pub mod primitives;
9|pub mod rope;
10|pub mod swiglu;
11|
12|// Re-export public API
13|pub use layer::{Attention, TransformerLayer};
14|pub use primitives::{Linear, RmsNorm};
15|pub use rope::RopeConfig;
16|pub use swiglu::SwiGLUFFN;
17|
18|// Re-export argmax from transformer_stub to avoid duplicate (already exported in lib.rs)
19|// pub use crate::transformer_stub::argmax; // Disabled - causes duplicate export
20|
21|/// CPU-only transformer model with full forward pass.
22|///
23|/// Unlike the stub version, this implementation loads real transformer layer weights
24|/// and performs complete autoregressive generation through all layers.
25|pub struct CpuTransformerModel {
26|    /// Model configuration extracted from GGUF header
27|    pub config: TransformerConfig,
28|    /// Token embeddings (vocab_size × embed_dim)
29|    pub token_embeddings: Linear,
30|    /// Transformer layers (one per depth)
31|    pub layers: Vec<TransformerLayer>,
32|    /// Final RMSNorm after all transformer layers
33|    pub final_norm: RmsNorm,
34|    /// Output projection (embed_dim × vocab_size)
35|    pub output_proj: Linear,
36|}
37|
38|/// Configuration for a CPU transformer model.
39|#[derive(Debug)]
40|pub struct TransformerConfig {
41|    pub num_layers: usize,
42|    pub num_heads: usize,
43|    pub num_kv_heads: usize,
44|    pub head_dim: usize,
45|    pub embed_dim: usize,
46|    pub intermediate_dim: usize,
47|    pub vocab_size: usize,
48|    pub max_seq_len: usize,
49|    pub rope_base: f32,
50|    pub rms_norm_eps: f32,
51|}
52|
53|impl CpuTransformerModel {
54|    /// Create a new CPU transformer model from loaded weights.
55|    ///
56|    /// This is a minimal implementation that loads only the necessary tensors for
57|    /// single-token generation (embeddings + one layer as proof of concept).
58|    pub fn new(
59|        token_embeddings: Vec<f32>,
60|        layers: Vec<TransformerLayer>,
61|        final_norm: RmsNorm,
62|        output_proj: Linear,
63|        config: TransformerConfig,
64|    ) -> Self {
65|        Self {
66|            token_embeddings: Linear::new(token_embeddings, None, 1, config.embed_dim),
67|            layers,
68|            final_norm,
69|            output_proj,
70|            config,
71|        }
72|    }
73|
74|    /// Forward pass through all transformer layers.
75|    ///
76|    /// - Input: `[embed_dim]` (single token's hidden state)
77|    /// - Position: `pos` (for RoPE)
78|    /// - Returns: `[embed_dim]` (output logits before softmax)
79|    pub fn forward(&self, hidden: &[f32], pos: usize) -> Result<Vec<f32>, String> {
80|        let mut x = hidden.to_vec();
81|
82|        // Pass through each transformer layer
83|        for (layer_idx, layer) in self.layers.iter().enumerate() {
84|            x = layer.forward_with_cache_single(&x, pos)?;
85|            eprintln!("Layer {} complete", layer_idx);
86|        }
87|
88|        // Apply final RMSNorm
89|        x = self.final_norm.forward(&x, 1);
90|
91|        // Project to vocab space
92|        let logits = self.output_proj.forward(&x, 1);
93|
94|        Ok(logits)
95|    }
96|
97|    /// Generate next token from input tokens (autoregressive).
98|    ///
99|    /// - `token_ids`: input token IDs (single token for decode mode)
100|    /// - `pos`: current position in sequence
101|    /// - Returns: `(next_token, logits)` where logits is `[vocab_size]`
102|    pub fn generate(&self, token_ids: &[u32], pos: usize) -> Result<(u32, Vec<f32>), String> {
103|        // Embed token
104|        let hidden = self.embed_token(token_ids[0])?;
105|
106|        // Forward through transformer
107|        let logits = self.forward(&hidden, pos)?;
108|
109|        // Sample next token (simple argmax for now)
110|        let next_token = argmax(&logits);
111|
112|        Ok((next_token, logits))
113|    }
114|
115|    /// Embed a single token ID into hidden space.
116|    fn embed_token(&self, token_id: u32) -> Result<Vec<f32>, String> {
117|        if (token_id as usize) >= self.config.vocab_size {
118|            return Err(format!(
119|                "Token ID {} exceeds vocab size {}",
120|                token_id, self.config.vocab_size
121|            ));
122|        }
123|
124|        // Simple lookup: each row is embed_dim elements
125|        let start = token_id as usize * self.config.embed_dim;
126|        let end = start + self.config.embed_dim;
127|
128|        Ok(self.token_embeddings.weight[start..end].to_vec())
129|    }
130|
131|    /// Get model configuration.
132|    pub fn config(&self) -> &TransformerConfig {
133|        &self.config
134|    }
135|}
136|
137|// Re-export argmax from transformer_stub to avoid duplicate
138|pub use crate::transformer_stub::argmax;
139|
140|/// Softmax sampling with temperature.
141|pub fn sample_with_temp(logits: &[f32], temp: f32, _rng: &mut rand::rngs::StdRng) -> u32 {
142|    // Apply temperature
143|    let scaled: Vec<f32> = logits.iter().map(|&x| x / temp).collect();
144|
145|    // Softmax
146|    let max_val = scaled.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
147|    let exps: Vec<f32> = scaled.iter().map(|&x| (x - max_val).exp()).collect();
148|    let sum: f32 = exps.iter().sum();
149|    let probs: Vec<f32> = exps.iter().map(|&e| e / sum).collect();
150|
151|    // Categorical sampling (placeholder - just return first token for now)
152|    0u32
153|}
