{"content": "1|//! Full forward pass through transformer layers (CPU-only).
2|//!
3|//! Demonstrates loading GGUF weights with proper dequantization using pesti-runner's
4|//! built-in CpuTransformerModel, which handles Q4_K/Q5_K/Q6_K quantization correctly.
5|
6|use std::path::Path;
7|use std::time::Instant;
8|
9|fn main() -> Result<(), Box<dyn std::error::Error>> {
10|    let model_path =
11|        "/home/crombo/projects/pesti/conformance-corpus/qwen2.5-0.5b-instruct-q4_k_m.gguf";
12|
13|    println!("Loading model from: {}", model_path);
14|    let load_start = Instant::now();
15|
16|    // Use pesti-runner's built-in loader which handles dequantization correctly
17|    let weights = pesti_runner::load_gguf_weights(Path::new(model_path))?;
18|
19|    // Extract config
20|    let embed_dim = weights.header.embedding_length().unwrap_or(896) as usize;
21|    let num_heads = weights
22|        .header
23|        .get_kv_u32("llama.attention.head_count")
24|        .unwrap_or(8) as usize;
25|    let num_kv_heads = weights
26|        .header
27|        .get_kv_u32("llama.attention.head_count_kv")
28|        .unwrap_or(8) as usize;
29|    let num_layers = weights.header.block_count().unwrap_or(24) as usize;
30|    let head_dim = if num_heads > 0 {
31|        embed_dim / num_heads
32|    } else {
33|        64
34|    };
35|
36|    // Infer vocab_size from actual token_embd.weight tensor size
37|    let _token_embd_tensor = weights
38|        .tensors
39|        .get("token_embd.weight")
40|        .ok_or("Missing token_embd.weight")?;
41|    let (embed_dim_inferred, vocab_size) = weights.tensor_shape("token_embd.weight");
42|    let vocab_size = if embed_dim_inferred > 0 {
43|        vocab_size
44|    } else {
45|        32000
46|    };
47|
48|    let config = pesti_runner::transformer_cpu::TransformerConfig {
49|        num_layers,
50|        num_heads,
51|        num_kv_heads,
52|        head_dim,
53|        embed_dim,
54|        intermediate_dim: weights
55|            .header
56|            .get_kv_u32("llama.feed_forward_length")
57|            .unwrap_or(4096) as usize,
58|        vocab_size,
59|        max_seq_len: 2048,
60|        rope_base: 10000.0,
61|        rms_norm_eps: 1e-5,
62|    };
63|
64|    println!(
65|        "✓ Model metadata extracted in {:.2}s",
66|        load_start.elapsed().as_secs_f32()
67|    );
68|    println!("  - Architecture: Qwen2");
69|    println!("  - Layers: {}", num_layers);
70|    println!("  - Embedding dim: {}", embed_dim);
71|    println!("  - Num heads: {}", num_heads);
72|    println!("  - Num KV heads: {}", num_kv_heads);
73|    println!("  - Head dim: {}", head_dim);
74|    println!("  - Vocab size (inferred): {}", vocab_size);
75|
76|    // Load token embeddings - GGUF stores as [embed_dim, vocab_size] (transposed!)
77|    let token_embeddings_data = weights
78|        .tensors
79|        .get("token_embd.weight")
80|        .ok_or("Missing token_embd.weight")?;
81|
82|    // Convert dequantized bytes to f32
83|    let raw_embeddings: Vec<f32> = token_embeddings_data
84|        .chunks_exact(4)
85|        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
86|        .collect();
87|
88|    // Transpose: convert from [embed_dim, vocab_size] to [vocab_size, embed_dim]
89|    let mut token_embeddings = vec![0.0f32; embed_dim * vocab_size];
90|    for row in 0..vocab_size {
91|        for col in 0..embed_dim {
92|            token_embeddings[row * embed_dim + col] = raw_embeddings[col * vocab_size + row];
93|        }
94|    }
95|
96|    println!(
97|        "✓ Loaded & transposed token embeddings: {} elements",
98|        token_embeddings.len()
99|    );
100|
101|    // Load transformer layers using pesti-runner's CpuTransformerModel components
102|    let mut layers = Vec::with_capacity(num_layers);
103|
104|    for layer_idx in 0..num_layers {
105|        // Get attention weights (already dequantized)
106|        let wq_data = weights
107|            .tensors
108|            .get(&format!("blk.{}.attn.q_proj.weight", layer_idx))
109|            .ok_or("Missing attn_q.weight")?;
110|        let wk_data = weights
111|            .tensors
112|            .get(&format!("blk.{}.attn.k_proj.weight", layer_idx))
113|            .ok_or("Missing attn_k.weight")?;
114|        let wv_data = weights
115|            .tensors
116|            .get(&format!("blk.{}.attn.v_proj.weight", layer_idx))
117|            .ok_or("Missing attn_v.weight")?;
118|        let wo_data = weights
119|            .tensors
120|            .get(&format!("blk.{}.attn.o_proj.weight", layer_idx))
121|            .ok_or("Missing attn_output.weight")?;
122|
123|        // Convert dequantized bytes to f32
124|        let wq: Vec<f32> = wq_data
125|            .chunks_exact(4)
126|            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
127|            .collect();
128|        let wk: Vec<f32> = wk_data
129|            .chunks_exact(4)
130|            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
131|            .collect();
132|        let wv: Vec<f32> = wv_data
133|            .chunks_exact(4)
134|            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
135|            .collect();
136|        let wo: Vec<f32> = wo_data
137|            .chunks_exact(4)
138|            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
139|            .collect();
140|
141|        // Get FFN weights (already dequantized)
142|        let w1_data = weights
143|            .tensors
144|            .get(&format!("blk.{}.ffn_gate_proj.weight", layer_idx))
145|            .ok_or("Missing ffn_gate.weight")?;
146|        let w2_data = weights
147|            .tensors
148|            .get(&format!("blk.{}.ffn_down_proj.weight", layer_idx))
149|            .ok_or("Missing ffn_down.weight")?;
150|        let w3_data = weights
151|            .tensors
152|            .get(&format!("blk.{}.ffn_up_proj.weight", layer_idx))
153|            .ok_or("Missing ffn_up.weight")?;
154|
155|        // Convert dequantized bytes to f32
156|        let w1: Vec<f32> = w1_data
157|            .chunks_exact(4)
158|            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
159|            .collect();
160|        let w2: Vec<f32> = w2_data
161|            .chunks_exact(4)
162|            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
163|            .collect();
164|        let w3: Vec<f32> = w3_data
165|            .chunks_exact(4)
166|            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
167|            .collect();
168|
169|        // Get actual dimensions from tensor shape (logical dimensions, not storage)
170|        let gate_shape = weights.tensor_shape(&format!("blk.{}.ffn_gate_proj.weight", layer_idx));
171|        let down_shape = weights.tensor_shape(&format!("blk.{}.ffn_down_proj.weight", layer_idx));
172|        let up_shape = weights.tensor_shape(&format!("blk.{}.ffn_up_proj.weight", layer_idx));
173|
174|        println!(
175|            "DEBUG: FFN shapes - gate {:?}, down {:?}, up {:?}",
176|            gate_shape, down_shape, up_shape
177|        );
178|
179|        // Transpose FFN weights - GGUF stores as [in_features, out_features], Linear expects [out_features, in_features]
180|        let mut w1_transposed = vec![0.0f32; gate_shape.1 * gate_shape.0];
181|        for row in 0..gate_shape.1 {
182|            for col in 0..gate_shape.0 {
183|                w1_transposed[row * gate_shape.0 + col] = w1[col * gate_shape.1 + row];
184|            }
185|        }
186|
187|        let mut w2_transposed = vec![0.0f32; down_shape.1 * down_shape.0];
188|        for row in 0..down_shape.1 {
189|            for col in 0..down_shape.0 {
190|                w2_transposed[row * down_shape.0 + col] = w2[col * down_shape.1 + row];
191|            }
192|        }
193|
194|        let mut w3_transposed = vec![0.0f32; up_shape.1 * up_shape.0];
195|        for row in 0..up_shape.1 {
196|            for col in 0..up_shape.0 {
197|                w3_transposed[row * up_shape.0 + col] = w3[col * up_shape.1 + row];
198|            }
199|        }
200|
201|        let attention = pesti_runner::transformer_cpu::Attention::new(
202|            wq,
203|            wk,
204|            wv,
205|            wo,
206|            pesti_runner::transformer_cpu::RopeConfig::new(embed_dim / 2, 10000.0, 2048),
207|            num_heads,
208|            num_kv_heads,
209|            head_dim,
210|        );
211|
212|        let feed_forward = pesti_runner::transformer_cpu::SwiGLUFFN::new(
213|            w1_transposed,
214|            w2_transposed,
215|            w3_transposed,
216|            embed_dim,
217|        );
218|
219|        let layer = pesti_runner::transformer_cpu::TransformerLayer::new(
220|            pesti_runner::transformer_cpu::RmsNorm::new(1e-5, embed_dim), // attn_norm
221|            attention,
222|            pesti_runner::transformer_cpu::RmsNorm::new(1e-5, embed_dim), // ffn_norm
223|            feed_forward,
224|        );
225|
226|        layers.push(layer);
227|    }
228|
229|    println!("✓ Loaded {} transformer layers", layers.len());
230|
231|    // Load final norm
232|    let final_norm = pesti_runner::transformer_cpu::RmsNorm::new(1e-5, embed_dim);
233|
234|    // Load output projection - GGUF stores as [embed_dim, vocab_size] (transposed!)
235|    let output_data = weights
236|        .tensors
237|        .get("output.weight")
238|        .ok_or("Missing output.weight")?;
239|
240|    let (in_feat, out_feat) = weights.tensor_shape("output.weight");
241|    println!(
242|        "DEBUG: output.weight shape from GGUF: [{}x{}]",
