298|/// Simple 64-bit hash for output comparison.
299|fn simple_hash<T: Hash + ?Sized>(data: &T) -> u64 {
300|    let mut s = DefaultHasher::new();
301|    data.hash(&mut s);
302|    s.finish()
303|}
304|
305|/// Find the index of the maximum value in a slice (argmax).
306|fn argmax(v: &[f32]) -> usize {
307|    v.iter()
308|        .enumerate()
309|        .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal))
310|        .map(|(i, _)| i)
311|        .unwrap_or(0)
312|}
