346|/// Write floor file with current pass count for CI gating.
347|fn write_floor_file(path: &Path, pass_count: usize) -> Result<()> {
348|    // Ensure parent directory exists
349|    if let Some(parent) = path.parent() {
350|        fs::create_dir_all(parent)?;
351|    }
352|
353|    // Write pass count to file
354|    let mut file = File::create(path)?;
355|    writeln!(file, "{}", pass_count)?;
356|
357|    tracing::info!("Wrote floor file: {} models passed", pass_count);
358|    Ok(())
359|}
