361|/// Delta-minimize a divergence between two outputs.
362|pub fn delta_minimize(expected: &[u8], actual: &[u8]) -> DivergenceInfo {
363|    let changes: Vec<DivergenceChange> = expected
364|        .iter()
365|        .zip(actual.iter())
366|        .enumerate()
367|        .filter_map(|(i, (e, a))| {
368|            if e != a {
369|                Some(DivergenceChange {
370|                    position: i,
371|                    expected: *e,
372|                    actual: *a,
373|                })
374|            } else {
375|                None
376|            }
377|        })
378|        .collect();
379|
380|    DivergenceInfo {
381|        divergence_offset: changes.first().map(|c| c.position),
382|        changes,
383|        total_bytes_expected: expected.len(),
384|        total_bytes_actual: actual.len(),
385|    }
386|}
